using System;using System.IO;using System.Drawing;using System.Drawing.Printing;using EanEtikety;
class OutputTests{static string dir;static void Check(bool value,string text){if(!value)throw new Exception(text);}[STAThread]static void Main(string[] a){dir=Path.GetFullPath(a[0]);Directory.CreateDirectory(dir);try{Run();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS empty document, immutable snapshot, three pages, last-page preview, portrait/landscape PDF at physical size; Microsoft Print to PDF only.");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
static void Run(){var empty=LabelSettings.Default();empty.Ean="";empty.Texts.Clear();bool rejected=false;try{using(var d=new LabelPrintDocument(empty)){} }catch(InvalidOperationException){rejected=true;}Check(rejected,"empty document");using(var cancelled=new LabelPrintDocument(LabelSettings.Default())){cancelled.PrintController=new PreviewPrintController();cancelled.BeginPrint+=delegate(object sender,PrintEventArgs e){e.Cancel=true;};cancelled.Print();Check(cancelled.Cancelled,"cancel before submission");}foreach(bool landscape in new[]{false,true}){var s=LabelSettings.Default();s.UsePaper=true;s.PageWidth=210;s.PageHeight=297;s.MarginX=12;s.MarginY=15;s.Copies=3;s.Symbols.Add(new SymbolItem{X=45,Y=28,Width=10,Height=10*DepositArt.Aspect});using(var doc=new LabelPrintDocument(s)){s.MarginX=90;Check(doc.LabelBounds(0).X==12,"snapshot immutable");doc.PrinterSettings.PrinterName="Microsoft Print to PDF";Check(doc.PrinterSettings.IsValid,"PDF driver");foreach(PaperSize size in doc.PrinterSettings.PaperSizes)if(size.Kind==PaperKind.A4){doc.DefaultPageSettings.PaperSize=size;break;}doc.DefaultPageSettings.Landscape=landscape;doc.ValidatePrinter();var control=new PreviewPrintController{UseAntiAlias=true};doc.PrintController=control;doc.Print();var pages=control.GetPreviewPageInfo();Check(pages.Length==3,"3 pages");int width=landscape?1170:827,height=landscape?827:1170;using(var bmp=new Bitmap(width,height))using(var g=Graphics.FromImage(bmp)){g.Clear(Color.White);g.DrawImage(pages[0].Image,new Rectangle(0,0,width,height));bmp.Save(Path.Combine(dir,landscape?"landscape-preview.png":"portrait-preview.png"));}foreach(var p in pages)p.Image.Dispose();doc.PrinterSettings.Copies=1;doc.PrinterSettings.PrintToFile=true;doc.PrinterSettings.PrintFileName=Path.Combine(dir,landscape?"landscape.pdf":"portrait.pdf");doc.PrintController=new StandardPrintController();doc.Print();}}}}
